import { isMobileAppVersionNotSupported, minMobileAppVersionRecordsUpload } from '@common/mobile'
import { AppInfo } from '@core/app/appInfo'
import SystemError from '@core/systemError'

import Job from '@server/job/job'
import * as ArenaSurveyFileZip from '@server/modules/arenaImport/service/arenaImport/model/arenaSurveyFileZip'
import FileZip from '@server/utils/file/fileZip'

const checkMobileAppVersionSupported = async (arenaSurveyFileZip) => {
  const { appInfo } = (await ArenaSurveyFileZip.getInfo(arenaSurveyFileZip)) ?? {}
  // files generated by Arena itself (or without info) are not subject to the mobile app version check
  if (!appInfo || AppInfo.getAppId(appInfo) === AppInfo.arenaAppId) return

  const { version: appVersion } = appInfo
  const minVersion = minMobileAppVersionRecordsUpload
  if (isMobileAppVersionNotSupported({ appVersion, minVersion })) {
    throw new SystemError('mobileAppVersionNotSupported', { appVersion, minVersion })
  }
}

export default class ArenaFileReadJob extends Job {
  constructor(params) {
    super(ArenaFileReadJob.type, params)
  }

  async execute() {
    const { context } = this
    const { filePath } = context

    const arenaSurveyFileZip = new FileZip(filePath)
    await arenaSurveyFileZip.init()

    this.setContext({ arenaSurveyFileZip })

    await checkMobileAppVersionSupported(arenaSurveyFileZip)
  }
}

ArenaFileReadJob.type = 'ArenaFileReadJob'
